   328|async function walkInspectableFiles(relDir: string, results: string[], max: number, projectRoot: string): Promise<void> {
   329|  if (results.length >= max) return;
   330|  const absDir = path.join(projectRoot, relDir);
   331|  let entries: string[];
   332|  try {
   333|    entries = await readdir(absDir);
   334|  } catch {
   335|    return;
   336|  }
   337|  for (const entry of entries) {
   338|    if (results.length >= max) return;
   339|    const relEntry = relDir ? `${relDir}/${entry}` : entry;
   340|    const absEntry = path.join(absDir, entry);
   341|    let info;
   342|    try {
   343|      info = await stat(absEntry);
   344|    } catch {
   345|      continue;
   346|    }
