   360|function pickInspectionTargets(goal: string, availableFiles: string[]): string[] {
   361|  const alwaysInclude = [
   362|    'backend/services/ivx-autonomous-coder-pilot.ts',
   363|    'backend/services/ivx-senior-developer-worker.ts',
   364|    'backend/services/ivx-senior-developer-runtime.ts',
