   366|    'backend/api/ivx-owner-ai.ts',
   367|    'backend/hono.ts',
   368|    'render.yaml',
   369|    'package.json',
   370|  ].filter((f) => availableFiles.includes(f));
   371|
   372|  const words = Array.from(new Set(
   373|    goal.toLowerCase()
   374|      .replace(/[^a-z0-9\s]/g, ' ')
   375|      .split(/\s+/)
   376|      .filter((w) => w.length >= 4)
   377|      .filter((w) => !['that', 'this', 'with', 'from', 'have', 'please', 'change', 'deploy', 'anything', 'current', 'status', 'label', 'version'].includes(w)),
   378|  ));
   379|
   380|  const hintMatches = availableFiles
   381|    .filter((f) => words.some((w) => f.toLowerCase().includes(w)))
   382|    .slice(0, 15);
   383|
   384|  // Also include files whose CONTENT might contain the goal's significant terms.
   385|  // This is handled in the inspect phase by reading file previews.
   386|
   387|  return Array.from(new Set([...alwaysInclude, ...hintMatches])).slice(0, MAX_INSPECTED_FILES);
