   390|async function readFilePreview(relPath: string, projectRoot: string): Promise<{ path: string; content: string; bytes: number } | null> {
   391|  try {
   392|    const absPath = path.join(projectRoot, relPath);
   393|    const content = await readFile(absPath, 'utf8');
   394|    const bytes = Buffer.byteLength(content, 'utf8');
   395|    // Send full content for small files so the LLM can copy oldText verbatim.
   396|    const preview = bytes <= FULL_CONTENT_THRESHOLD ? content : truncate(content, FILE_PREVIEW_CHARS);
   397|    return { path: relPath, content: preview, bytes };
   398|  } catch {
   399|    return null;
   400|  }
