   403|// ── PATCH APPLICATION ────────────────────────────────────────────────────────
   404|
   405|/** Paths the autonomous coder is allowed to modify. */
   406|const ALLOWED_PATCH_PATHS = /^((?:backend|expo)\/[A-Za-z0-9_.\/-]+\.ts$|(?:backend|expo)\/[A-Za-z0-9_.\/-]+\.tsx$|expo\/[A-Za-z0-9_.\/-]+\.json$|expo\/[A-Za-z0-9_.\/-]+\.gradle$)/;
   407|
   408|function assertSafePatchPath(filePath: string): void {
   409|  if (filePath.includes('..') || filePath.startsWith('/')) {
   410|    throw new Error(`Unsafe patch path rejected: ${filePath}`);
   411|  }
   412|  if (!ALLOWED_PATCH_PATHS.test(filePath)) {
   413|    throw new Error(`Patch path outside allowed roots: ${filePath}. Only backend/*.ts, expo/*.ts(x), expo/*.json, expo/*.gradle are permitted.`);
   414|  }
