   416|
   417|async function applyPatchOperation(
   418|  op: IVXAutonomousCoderPatchOperation,
   419|  projectRoot: string,
   420|  fileWriter?: (relPath: string, content: string) => Promise<void>,
   421|  fileReader?: (relPath: string) => Promise<string>,
   422|): Promise<void> {
   423|  assertSafePatchPath(op.path);
   424|  const fullPath = path.join(projectRoot, op.path);
   425|  const write = fileWriter ?? (async (rel: string, content: string) => {
   426|    await mkdir(path.dirname(path.join(projectRoot, rel)), { recursive: true });
   427|    await writeFile(path.join(projectRoot, rel), content, 'utf8');
   428|  });
   429|  const read = fileReader ?? (async (rel: string) => readFile(path.join(projectRoot, rel), 'utf8'));
   430|  if (op.kind === 'create_file') {
   431|    const { existsSync } = await import('node:fs');
   432|    if (existsSync(fullPath)) {
   433|      throw new Error(`Create-file target already exists: ${op.path}`);
   434|    }
   435|    await write(op.path, op.newText);
   436|  } else {
   437|    const source = await read(op.path);
   438|    if (!source.includes(op.oldText)) {
   439|      throw new Error(`Patch oldText not found in ${op.path}; cannot apply safely.`);
   440|    }
   441|    const updated = source.replace(op.oldText, op.newText);
   442|    await write(op.path, updated);
   443|  }
   444|}
