   471|async function runCommand(cwd: string, command: string): Promise<IVXAutonomousCoderTestResult> {
   472|  const started = Date.now();
   473|  // Resolve the runtime: the Render container runs under node+tsx, not bun.
   474|  // `bun test` and `bun x tsc` fail with ENOENT on the production container, so
   475|  // we resolve the runtime via resolveRuntimeCommand and translate the command
   476|  // to its node-based equivalent when bun is not available.
   477|  const parts = command.split(/\s+/);
   478|  const requestedRuntime = parts[0] as 'bun' | 'bunx' | 'node' | 'npx';
   479|  const resolution = resolveRuntimeCommand(requestedRuntime);
   480|  let effectiveCmd = resolution.resolvedPath ?? resolution.effectiveCommand;
   481|  let effectiveArgs = parts.slice(1);
   482|  let displayCommand = command;
   483|  // When bun falls back to node, translate `bun test <file>` → `node --test <file>`
   484|  // (node:test runner) and `bun x tsc --noEmit` → `npx tsc --noEmit` (or node tsc).
   485|  if (resolution.usedFallback && requestedRuntime === 'bun') {
   486|    if (effectiveArgs[0] === 'test') {
   487|      effectiveArgs = ['--test', ...effectiveArgs.slice(1)];
   488|      displayCommand = `node --test ${effectiveArgs.slice(1).join(' ')}`;
   489|    } else if (effectiveArgs[0] === 'x') {
   490|      // `bun x tsc` → use npx instead
   491|      const npxRes = resolveRuntimeCommand('npx');
