   566|function buildPatchUserPrompt(goal: string, files: { path: string; content: string }[], failureContext: string | null): string {
   567|  const fileBlocks = files.map((f) => `--- FILE: ${f.path} ---\n${f.content}`).join('\n\n');
   568|  const failureBlock = failureContext
   569|    ? `\n\n--- PREVIOUS ATTEMPT FAILED ---\n${failureContext}\n\nRevise the patch to fix the failure. Output the corrected JSON.`
   570|    : '';
   571|  return `GOAL:\n${goal}\n\nFILES:\n${fileBlocks}${failureBlock}`;
   572|}
   573|
   574|function parseLLMPatchResponse(response: string): { rootCause: string; technicalPlan: string; operations: IVXAutonomousCoderPatchOperation[] } | null {
   575|  try {
   576|    // Strip markdown code fences if present
   577|    const cleaned = response.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
   578|    // Find the first { and last }
   579|    const start = cleaned.indexOf('{');
   580|    const end = cleaned.lastIndexOf('}');
   581|    if (start < 0 || end < 0 || end <= start) return null;
   582|    const jsonStr = cleaned.slice(start, end + 1);
   583|    const parsed = JSON.parse(jsonStr) as {
   584|      rootCause?: string;
   585|      technicalPlan?: string;
   586|      operations?: Array<{
   587|        path?: string;
   588|        kind?: string;
   589|        oldText?: string;
   590|        newText?: string;
   591|        reason?: string;
   592|      }>;
   593|    };
   594|    if (!Array.isArray(parsed.operations)) return null;
   595|    const operations: IVXAutonomousCoderPatchOperation[] = [];
   596|    for (const op of parsed.operations) {
   597|      if (typeof op.path !== 'string' || typeof op.kind !== 'string') continue;
   598|      if (op.kind !== 'replace_exact' && op.kind !== 'create_file') continue;
   599|      if (typeof op.oldText !== 'string' || typeof op.newText !== 'string') continue;
   600|      operations.push({
   601|        path: op.path,
   602|        kind: op.kind,
   603|        oldText: op.oldText,
   604|        newText: op.newText,
   605|        reason: typeof op.reason === 'string' ? op.reason : '',
   606|      });
   607|    }
   608|    if (operations.length === 0) return null;
   609|    return {
   610|      rootCause: typeof parsed.rootCause === 'string' ? parsed.rootCause : 'LLM-generated patch',
   611|      technicalPlan: typeof parsed.technicalPlan === 'string' ? parsed.technicalPlan : 'Replace exact text per operations',
   612|      operations,
   613|    };
   614|  } catch {
   615|    return null;
   616|  }
