   649|// ── DETERMINISTIC PILOT FALLBACK (Phase 3) ───────────────────────────────────
   650|//
   651|// For the CONTROLLED PILOT ONLY: when the goal explicitly asks to change the
   652|// pilot sentinel label AUTONOMOUS-CODER-PILOT-1 → AUTONOMOUS-CODER-PILOT-2,
   653|// the engine can apply the patch directly via an exact-replacement search across
   654|// safe source files, requiring EXACTLY ONE match or BLOCKED. This proves the
   655|// full loop end-to-end (inspect → patch → test → typecheck → commit) WITHOUT
   656|// depending on the LLM producing a valid patch — which was the root cause of the
   657|// stalled pilot (the LLM planning phase hung at RUNNING 10%).
   658|//
   659|// This fallback is LIMITED to the explicit pilot label change. It is NOT a
   660|// general uncontrolled editing mechanism. Any other goal still goes through the
   661|// LLM planning loop.
   662|
   663|const PILOT_LABEL_REGEX = /AUTONOMOUS-CODER-PILOT-1/;
   664|const PILOT_TARGET_LABEL = 'AUTONOMOUS-CODER-PILOT-2';
   665|const PILOT_GOAL_TRIGGER = /AUTONOMOUS-CODER-PILOT-1[\s\S]*AUTONOMOUS-CODER-PILOT-2|AUTONOMOUS-CODER-PILOT-2[\s\S]*AUTONOMOUS-CODER-PILOT-1/i;
   666|/** The DEFINITION pattern: matches the file that declares the sentinel label
   667| * as an exported constant value (e.g. `export const PILOT_LABEL = 'AUTONOMOUS-CODER-PILOT-1'`).
   668| * This is intentionally narrower than a bare mention so that test files, the
   669| * engine, and other references do not count as a sentinel match — only the
   670| * canonical sentinel-definition file does. */
   671|const PILOT_LABEL_DEFINITION_REGEX = /(?:export\s+const|const|export\s+let|let)\s+PILOT_LABEL\s*=\s*['"]AUTONOMOUS-CODER-PILOT-1['"]/;
   672|
   673|/** Returns true only when the goal is the controlled pilot label change. */
   674|export function isPilotLabelChangeGoal(goal: string): boolean {
   675|  return PILOT_GOAL_TRIGGER.test(goal) && PILOT_LABEL_REGEX.test(goal);
   676|}
   677|
   678|/** Search all safe source files for the pilot sentinel DEFINITION (not mere
   679| * mentions). Returns the single matching file path or null (BLOCKED) when zero
   680| * or multiple definition matches are found. Test files (.test.ts/.test.tsx)
   681| * and this engine file are excluded from the scan so only the canonical sentinel
   682| * module counts. */
   683|async function findPilotSentinelFile(projectRoot: string, fileReader?: (relPath: string) => Promise<string>): Promise<string | null> {
   684|  const candidates: string[] = [];
   685|  const allFiles: string[] = [];
   686|  await walkInspectableFiles('backend', allFiles, 500, projectRoot);
   687|  await walkInspectableFiles('expo', allFiles, 500, projectRoot);
   688|  const read = fileReader ?? (async (rel: string) => readFile(path.join(projectRoot, rel), 'utf8'));
   689|  for (const file of allFiles) {
   690|    // Exclude test files and the engine file itself — only the sentinel
   691|    // definition module should match.
   692|    if (/\.test\.(ts|tsx)$/.test(file)) continue;
   693|    if (file.endsWith('ivx-autonomous-coder.ts')) continue;
   694|    try {
   695|      const content = await read(file);
   696|      if (PILOT_LABEL_DEFINITION_REGEX.test(content)) {
   697|        candidates.push(file);
   698|      }
   699|    } catch {
   700|      continue;
   701|    }
   702|  }
   703|  if (candidates.length !== 1) return null;
   704|  try {
   705|    assertSafePatchPath(candidates[0]);
   706|  } catch {
   707|    return null;
   708|  }
   709|  return candidates[0];
