   788|  const repoUrl = readEnv('GITHUB_REPO_URL');
   789|  const token = readEnv('GITHUB_TOKEN');
   790|  const repoInfo = parseGithubRepoUrl(repoUrl);
   791|  if (!repoInfo) throw new Error('GITHUB_REPO_URL is missing or invalid.');
   792|  if (!token) throw new Error('GITHUB_TOKEN is missing.');
   793|
   794|  const headers = {
   795|    Authorization: `Bearer ${token}`,
   796|    Accept: 'application/vnd.github+json',
   797|    'Content-Type': 'application/json',
   798|  };
   799|
   800|  // Read the branch ref
   801|  const refRes = await fetch(
   802|    `${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/ref/heads/${encodeURIComponent(branch)}`,
   803|    { headers, signal: AbortSignal.timeout(10000) },
   804|  );
   805|  if (!refRes.ok) throw new Error(`GitHub branch ref lookup failed: ${refRes.status}`);
   806|  const refData = await refRes.json() as { object?: { sha?: string } };
   807|  const baseCommitSha = refData.object?.sha;
   808|  if (!baseCommitSha) throw new Error('GitHub branch ref did not include a commit SHA.');
   809|
   810|  // Get the base commit's tree
