   812|    `${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/commits/${encodeURIComponent(baseCommitSha)}`,
   813|    { headers, signal: AbortSignal.timeout(10000) },
   814|  );
   815|  if (!commitRes.ok) throw new Error(`GitHub base commit lookup failed: ${commitRes.status}`);
   816|  const commitData = await commitRes.json() as { tree?: { sha?: string } };
   817|  const baseTreeSha = commitData.tree?.sha;
   818|  if (!baseTreeSha) throw new Error('GitHub base commit did not include a tree SHA.');
   819|
   820|  // Create the new tree with the changed files
   821|  const tree = await Promise.all(filePaths.map(async (repoPath) => ({
   822|    path: repoPath,
   823|    mode: '100644' as const,
   824|    type: 'blob' as const,
   825|    content: await readFile(path.join(DEFAULT_PROJECT_ROOT, repoPath), 'utf8'),
