   830|    {
   831|      method: 'POST',
   832|      headers,
   833|      body: JSON.stringify({ base_tree: baseTreeSha, tree }),
   834|      signal: AbortSignal.timeout(15000),
   835|    },
   836|  );
   837|  if (!treeRes.ok) throw new Error(`GitHub tree creation failed: ${treeRes.status}`);
   838|  const treeData = await treeRes.json() as { sha?: string };
   839|  const newTreeSha = treeData.sha;
   840|  if (!newTreeSha) throw new Error('GitHub tree creation did not return a tree SHA.');
   841|
   842|  // Create the commit
