   906|// ── PRODUCTION ROLLBACK (Phase 16) ────────────────────────────────────────────
   907|//
   908|// When a deploy verifies-fail (health check returns a different commit, or the
   909|// health endpoint is down after the deploy), the engine attempts an automatic
   910|// rollback: it fetches the parent of the just-deployed commit, creates a revert
   911|// commit that restores the prior tree, pushes it to the branch, and re-triggers
   912|// a Render deploy of the revert commit. This is bounded — one attempt — and any
   913|// failure is recorded in rollbackError (the engine never silently swallows a
   914|// rollback failure).
   915|
   916|async function getCommitParentSha(owner: string, repo: string, token: string, commitSha: string): Promise<string | null> {
   917|  try {
   918|    const res = await fetch(`${GITHUB_API_BASE_URL}/repos/${owner}/${repo}/git/commits/${encodeURIComponent(commitSha)}`, {
   919|      headers: { Authorization: `Bearer ${token}`, Accept: 'application/vnd.github+json' },
   920|      signal: AbortSignal.timeout(10000),
   921|    });
   922|    if (!res.ok) return null;
   923|    const data = await res.json() as { parents?: Array<{ sha?: string }> };
   924|    return data.parents?.[0]?.sha ?? null;
   925|  } catch { return null; }
   926|}
   927|
   928|async function rollbackProductionDeploy(commitSha: string, branch: string): Promise<{ reverted: boolean; revertCommitSha: string | null; error: string | null }> {
   929|  const repoUrl = readEnv('GITHUB_REPO_URL');
   930|  const token = readEnv('GITHUB_TOKEN');
   931|  const repoInfo = parseGithubRepoUrl(repoUrl);
   932|  if (!repoInfo || !token) return { reverted: false, revertCommitSha: null, error: 'Rollback aborted: GitHub credentials unavailable.' };
   933|  const headers = { Authorization: `Bearer ${token}`, Accept: 'application/vnd.github+json', 'Content-Type': 'application/json' };
   934|  // 1. Get the parent of the bad commit (the last known-good SHA).
   935|  const parentSha = await getCommitParentSha(repoInfo.owner, repoInfo.repo, token, commitSha);
   936|  if (!parentSha) return { reverted: false, revertCommitSha: null, error: `Could not resolve parent of ${commitSha}.` };
   937|  // 2. Get the parent commit's tree.
   938|  let parentTreeSha: string | null = null;
   939|  try {
   940|    const res = await fetch(`${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/commits/${encodeURIComponent(parentSha)}`, { headers, signal: AbortSignal.timeout(10000) });
   941|    if (res.ok) {
   942|      const data = await res.json() as { tree?: { sha?: string } };
   943|      parentTreeSha = data.tree?.sha ?? null;
   944|    }
   945|  } catch { /* fall through */ }
   946|  if (!parentTreeSha) return { reverted: false, revertCommitSha: null, error: `Could not read parent tree for ${parentSha}.` };
   947|  // 3. Create a revert commit pointing at the parent's tree (restores prior files).
   948|  let revertCommitSha: string | null = null;
   949|  try {
   950|    const res = await fetch(`${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/commits`, {
   951|      method: 'POST', headers,
   952|      body: JSON.stringify({ message: `IVX autonomous coder ROLLBACK: revert ${commitSha.slice(0, 7)} (deploy verified-fail)`, tree: parentTreeSha, parents: [parentSha] }),
