   609|// ─────────────────────────────────────────────────────────────────────────────
   610|// STALE JOB EXPIRATION
   611|// ─────────────────────────────────────────────────────────────────────────────
   612|
   613|/** Statuses that are considered "active" (still in progress). */
   614|const ACTIVE_STATUSES: ReadonlySet<IVXWorkerJobStatus> = new Set([
   615|  'queued', 'running', 'patching', 'testing', 'committing', 'deploying', 'verifying',
   616|]);
   617|
   618|/**
   619| * Expire stale jobs whose `startedAt` is older than `STALE_JOB_TIMEOUT_MS`.
   620| * Stale jobs are marked FAILED with an honest reason. This frees the queue so
   621| * a new job can start for the same owner.
   622| *
   623| * @returns array of expired job IDs
   624| */
   625|export async function expireStaleJobs(): Promise<string[]> {
   626|  const queue = await loadQueue();
   627|  const now = Date.now();
   628|  const expired: string[] = [];
   629|
   630|  for (const job of queue.jobs) {
   631|    if (!ACTIVE_STATUSES.has(job.status)) continue;
   632|    if (!job.startedAt) continue;
   633|    const startedAtMs = new Date(job.startedAt).getTime();
   634|    if (Number.isNaN(startedAtMs)) continue;
   635|    if (now - startedAtMs > STALE_JOB_TIMEOUT_MS) {
   636|      job.status = 'failed';
   637|      job.stage = 'FAILED';
   638|      job.stageDetail = `Job expired after ${Math.round(STALE_JOB_TIMEOUT_MS / 1000)}s of inactivity.`;
   639|      job.finishedAt = nowIso();
   640|      job.error = `Stale job expired (timeout: ${STALE_JOB_TIMEOUT_MS}ms).`;
   641|      expired.push(job.jobId);
   642|    }
   643|  }
   644|
   645|  if (expired.length > 0) {
   646|    await saveQueue(queue);
   647|    for (const jobId of expired) {
   648|      appendDurableEvent(QUEUE_FILE, { type: 'job_expired', jobId, reason: 'stale_timeout' }).catch(() => {});
   649|    }
   650|  }
   651|
   652|  return expired;
   653|}
