   655|// ─────────────────────────────────────────────────────────────────────────────
   656|// PER-OWNER SINGLE-FLIGHT
   657|// ─────────────────────────────────────────────────────────────────────────────
   658|
   659|/**
   660| * Get the active (in-progress) job for a given owner. Returns null if no active
   661| * job exists. Also expires stale jobs before checking.
   662| */
   663|export async function getActiveJobForOwner(ownerId: string): Promise<IVXWorkerJob | null> {
   664|  if (!ownerId) return null;
   665|  await expireStaleJobs();
   666|  const queue = await loadQueue();
   667|  // Find the most recent active job for this owner.
   668|  for (let i = queue.jobs.length - 1; i >= 0; i -= 1) {
   669|    const job = queue.jobs[i];
   670|    if (job.ownerId === ownerId && ACTIVE_STATUSES.has(job.status)) {
   671|      return job;
   672|    }
   673|  }
   674|  return null;
   675|}
   676|
   677|/**
   678| * Result of an enqueue-or-attach operation. When `attached` is true, the job
   679| * already existed and the request was NOT discarded — the caller gets the
   680| * active job's ID. When `attached` is false, a new job was created.
   681| */
   682|export type EnqueueOrAttachResult = {
   683|  job: IVXWorkerJob;
   684|  attached: boolean;
   685|  /** The active job that was already running, if attached. */
   686|  activeJobId: string | null;
   687|};
   688|
   689|/**
   690| * Submit an owner-approved development task to the worker queue with per-owner
   691| * single-flight enforcement. If an active job already exists for the same
   692| * owner, the request ATTACHES to that job (returns its jobId) instead of
   693| * creating a duplicate or returning HTTP 409.
   694| *
   695| * The user's request is NEVER discarded:
   696| *   - If no active job exists → a new job is created and queued.
   697| *   - If an active job exists for the same owner → the request attaches to it.
   698| *   - If the active job is stale → it is expired and a new job is created.
   699| *
   700| * Owner approval MUST already be verified by the caller (API boundary).
   701| */
   702|export async function enqueueOrAttachSeniorDeveloperJob(input: IVXWorkerJobInput): Promise<EnqueueOrAttachResult> {
   703|  const goal = input.goal.trim();
   704|  if (!goal) throw new Error('A senior developer goal is required to enqueue a job.');
   705|  if (!input.ownerApproved) throw new Error('Cannot enqueue a senior developer job without verified owner approval.');
   706|
   707|  // FINAL MANDATE Phase 1: owner emergency stop halts all agent work at the enqueue boundary.
   708|  const emergencyStop = await checkEmergencyStop();
   709|  if (emergencyStop.active) {
   710|    throw new Error(
   711|      `EMERGENCY_STOP_ACTIVE: owner emergency stop is engaged (${emergencyStop.reason ?? 'no reason recorded'}); job enqueue refused.`,
   712|    );
   713|  }
   714|
   715|  const ownerId = input.ownerId ?? 'default';
   716|
   717|  // Check for an existing active job for this owner (also expires stale jobs).
   718|  const activeJob = await getActiveJobForOwner(ownerId);
   719|  if (activeJob) {
   720|    // ATTACH: return the existing running job. The request is NOT discarded.
   721|    return { job: activeJob, attached: true, activeJobId: activeJob.jobId };
   722|  }
   723|
   724|  // No active job — create a new one.
   725|  const job: IVXWorkerJob = {
   726|    jobId: `ivx-worker-${randomUUID()}`,
   727|    status: 'queued',
   728|    stage: 'QUEUED',
   729|    progressPercent: 0,
   730|    stageDetail: 'Job queued and waiting for worker.',
   731|    input: { ...input, goal },
   732|    ownerId,
   733|    createdAt: nowIso(),
   734|    startedAt: null,
   735|    finishedAt: null,
   736|    cancelledAt: null,
   737|    attempts: 0,
   738|    result: null,
   739|    error: null,
   740|  };
   741|
   742|  const queue = await loadQueue();
   743|  queue.jobs.push(job);
   744|  await saveQueue(queue);
   745|  appendDurableEvent(QUEUE_FILE, { type: 'job_enqueued', jobId: job.jobId, goal: goal.slice(0, 200), ownerId }).catch(() => {});
   746|
   747|  // Kick the worker without blocking the caller.
   748|  void drainSeniorDeveloperQueue();
   749|  return { job, attached: false, activeJobId: null };
   750|}
