   755|
   756|/**
   757| * Cancel a job. If the job is currently running, signals the controller to
   758| * stop. Marks the job as cancelled in the queue.
   759| */
   760|export async function cancelSeniorDeveloperJob(jobId: string): Promise<IVXWorkerJob | null> {
   761|  const queue = await loadQueue();
   762|  const idx = queue.jobs.findIndex((j) => j.jobId === jobId);
   763|  if (idx < 0) return null;
   764|  const job = queue.jobs[idx];
   765|
   766|  // Signal the running controller to stop (if one exists).
   767|  const controller = activeJobControllers.get(jobId);
   768|  if (controller) {
   769|    controller.cancelled = true;
   770|  }
   771|
   772|  job.status = 'cancelled';
   773|  job.stage = 'FAILED';
   774|  job.stageDetail = 'Job cancelled by owner.';
   775|  job.cancelledAt = nowIso();
   776|  job.finishedAt = nowIso();
   777|  queue.jobs[idx] = job;
   778|  await saveQueue(queue);
   779|  appendDurableEvent(QUEUE_FILE, { type: 'job_cancelled', jobId }).catch(() => {});
   780|  return job;
