   782|
   783|/**
   784| * Resume a queued or blocked job. If the job is already running, returns it
   785| * as-is (attach behavior). If the job is cancelled or completed, returns null.
   786| */
   787|export async function resumeSeniorDeveloperJob(jobId: string): Promise<IVXWorkerJob | null> {
   788|  const queue = await loadQueue();
   789|  const idx = queue.jobs.findIndex((j) => j.jobId === jobId);
   790|  if (idx < 0) return null;
   791|  const job = queue.jobs[idx];
   792|
   793|  // Can only resume queued or blocked jobs.
   794|  if (job.status !== 'queued' && job.status !== 'blocked') {
   795|    return job; // Return as-is for running jobs (attach behavior).
   796|  }
   797|
   798|  // Reset to queued so the drain loop picks it up.
   799|  job.status = 'queued';
   800|  job.stage = 'QUEUED';
   801|  job.progressPercent = 0;
   802|  job.stageDetail = 'Job resumed by owner.';
   803|  job.error = null;
   804|  queue.jobs[idx] = job;
   805|  await saveQueue(queue);
   806|  appendDurableEvent(QUEUE_FILE, { type: 'job_resumed', jobId }).catch(() => {});
   807|
   808|  // Kick the worker.
   809|  void drainSeniorDeveloperQueue();
   810|  return job;
